using System;
using System.Linq;

public static class InvoiceResponseMappings
{
    public static Invoice ToInvoice(this InvoiceResponse source)
    {
        ArgumentNullException.ThrowIfNull(source);
        return new Invoice
        {
            Id = source.InvoiceId,
            IssuedAt = source.IssuedAt,
            DueDate = source.DueDate,
            Status = Enum.Parse<InvoiceStatus>(source.Status),
            Total = (decimal)source.TotalCents / 100m,
            Currency = source.Currency,
            Notes = source.Notes is { } value ? value.ToString() : null,
            CustomerId = source.Customer.CustomerId,
            // TODO: no value for "customerName" in the mapping
            CustomerName = "",
            CustomerEmail = source.Customer.EmailAddress,
            BillingAddress = source.Customer.BillingAddress.ToAddress(),
            Items = source.Lines.Select(item => item.ToInvoiceItem()).ToList(),
            IsPaid = source.Paid,
            // TODO: no value for "createdBy" in the mapping
            CreatedBy = "",
        };
    }

    public static Address ToAddress(this BillingAddress source)
    {
        ArgumentNullException.ThrowIfNull(source);
        return new Address
        {
            Street = source.Street,
            City = source.City,
            PostalCode = source.ZipCode,
            CountryCode = source.Country,
        };
    }

    public static InvoiceItem ToInvoiceItem(this Line source)
    {
        ArgumentNullException.ThrowIfNull(source);
        return new InvoiceItem
        {
            Sku = source.Sku,
            Description = source.Description,
            Quantity = checked((int)source.Qty),
            UnitPrice = (decimal)source.UnitPriceCents / 100m,
            TaxRate = source.TaxRate,
        };
    }
}

