public class InvoiceResponseProfile : Profile
{
    public InvoiceResponseProfile()
    {
        CreateMap<InvoiceResponse, Invoice>()
            .ForMember(dest => dest.Id, opt => opt.MapFrom(src => src.InvoiceId))
            .ForMember(dest => dest.Total, opt => opt.MapFrom(src => (decimal)src.TotalCents / 100m))
            .ForMember(dest => dest.CustomerId, opt => opt.MapFrom(src => src.Customer.CustomerId))
            .ForMember(dest => dest.CustomerName, opt => opt.Ignore()) // TODO: no value in the mapping
            .ForMember(dest => dest.CustomerEmail, opt => opt.MapFrom(src => src.Customer.EmailAddress))
            .ForMember(dest => dest.BillingAddress, opt => opt.MapFrom(src => src.Customer.BillingAddress))
            .ForMember(dest => dest.Items, opt => opt.MapFrom(src => src.Lines))
            .ForMember(dest => dest.IsPaid, opt => opt.MapFrom(src => src.Paid))
            .ForMember(dest => dest.CreatedBy, opt => opt.Ignore()) // TODO: no value in the mapping;

        CreateMap<BillingAddress, Address>()
            .ForMember(dest => dest.PostalCode, opt => opt.MapFrom(src => src.ZipCode))
            .ForMember(dest => dest.CountryCode, opt => opt.MapFrom(src => src.Country));

        CreateMap<Line, InvoiceItem>()
            .ForMember(dest => dest.Quantity, opt => opt.MapFrom(src => src.Qty))
            .ForMember(dest => dest.UnitPrice, opt => opt.MapFrom(src => (decimal)src.UnitPriceCents / 100m));
    }
}

